def blocks(inp,sep):
    H,W=len(inp),len(inp[0])
    sr=[i for i in range(H) if all(v==sep for v in inp[i])]
    sc=[j for j in range(W) if all(inp[i][j]==sep for i in range(H))]
    def groups(idx):
        g=[];cur=[idx[0]]
        for x in idx[1:]:
            if x==cur[-1]+1:cur.append(x)
            else:g.append(cur);cur=[x]
        g.append(cur);return g
    return groups([r for r in range(H) if r not in sr]),groups([c for c in range(W) if c not in sc]),sr,sc
